import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'2vFXQV4acjGHUTy8Lsk1',titulo:'Câmera Veicular Ddpai N1 Dual 1296p+1080p 135° Nightvis App',listing:'MLB5460277774'},{id:'347WUiAlueVscYKR7Emm',titulo:'Robô Aspirador De Piscina Automático Redroad S1 Área 102 M2',listing:'MLB6968682598'}];
test('triagem50 preserva operação e afiliados, exige identidade e é idempotente',()=>{for(const r of rows){const p={...r,preco:'99,99',linkAfiliado:'https://meli.la/preservado',variation_id:'original'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{titulo:'Capa para '+r.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'},{id:'outro'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('DDPAI separa kit e áudio não confirmado de recursos documentados',()=>{const x=correctProductData(rows[0]);assert.equal(x.titulo,rows[0].titulo);assert.match(x.comentario,/cartão de 128 GB.*depende do kit/);assert.match(x.comentario,/áudio nas duas câmeras.*não foi confirmada/);assert.match(x.comentario,/kit de alimentação específico adquirido separadamente/);assert.doesNotMatch(x.pros,/128|áudio|placas|garant|elimina/i);});
test('Redroad mantém divergências explícitas sem certificar a unidade',()=>{const x=correctProductData(rows[1]);assert.match(x.titulo,/área e recarga a conferir/);assert.match(x.comentario,/102 m².*3 a 4 horas.*100 m².*4 a 5 horas/);assert.match(x.comentario,/Não escolhemos um desses números como garantia/);assert.match(x.comentario,/Não inferimos limpeza de paredes ou escadas/);assert.doesNotMatch(x.pros,/ideal|garant|102|parede|3 a 4/i);});
test('furadeira corrige só título cortado mantendo corpo e links',()=>{const p={id:'3AiculsXxRCfEkCx7Qin',titulo:'Furadeira De Impacto 13mm 750w Profissional Com Kit Brocas Buchas E Bits 300 Peças The Black Tools',comentario:'Texto do anúncio preservado',linkAfiliado:'https://meli.la/preservado'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.equal(x[k],p[k]);assert.match(x.titulo,/The Black Tools TBF750/);assert.ok(x.titulo.length<90);assert.deepEqual(correctProductData(x),x);assert.equal(x.pros,'');assert.equal(x.contras,'');for(const alt of [{titulo:'Capa para '+p.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,...alt}).titulo,alt.titulo||p.titulo);});
